'use strict';
// Step 7: verify answer.json structure and values against a fresh Node recomputation.
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const REGIONS = ['north', 'south', 'east', 'west'];

let failures = 0;
function check(name, ok, detail) {
  if (ok) {
    console.log(`PASS  ${name}${detail ? '  ' + detail : ''}`);
  } else {
    failures++;
    console.log(`FAIL  ${name}${detail ? '  ' + detail : ''}`);
  }
}
function fail(msg) {
  failures++;
  console.log(`FAIL  ${msg}`);
}
function isInt(n) {
  return typeof n === 'number' && Number.isFinite(n) && Number.isInteger(n) && n >= 0;
}
function sameKeys(obj, expected, label) {
  const actual = Object.keys(obj).sort();
  const want = [...expected].sort();
  const missing = want.filter((k) => !actual.includes(k));
  const extra = actual.filter((k) => !want.includes(k));
  check(`${label} keys`, missing.length === 0 && extra.length === 0,
    `expected [${want.join(',')}] got [${actual.join(',')}]` +
    (missing.length ? ` missing=[${missing.join(',')}]` : '') +
    (extra.length ? ` extra=[${extra.join(',')}]` : ''));
}

// --- 1. Independent recomputation from the four original datasets ---
const recomputed = {};
for (const region of REGIONS) {
  const file = path.join(dir, `${region}.json`);
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    fail(`cannot read ${region}.json: ${err.message}`);
    continue;
  }
  let records;
  try {
    records = JSON.parse(raw);
  } catch (err) {
    fail(`${region}.json is not valid JSON: ${err.message}`);
    continue;
  }
  if (!Array.isArray(records)) {
    fail(`${region}.json is not a top-level array`);
    continue;
  }
  if (records.length === 0) {
    fail(`${region}.json is empty`);
    continue;
  }
  let units = 0;
  let weighted = 0;
  let bad = 0;
  records.forEach((rec, i) => {
    if (!rec || typeof rec !== 'object') { bad++; return; }
    if (!isInt(rec.units) || !isInt(rec.weight)) { bad++; return; }
    units += rec.units;
    weighted += rec.units * rec.weight;
  });
  check(`${region} source records numeric`, bad === 0, `${records.length} records, ${bad} invalid`);
  recomputed[region] = { count: records.length, units, weighted };
  console.log(`      recomputed ${region}: count=${records.length} units=${units} weighted=${weighted}`);
}

// --- 2. Parse answer.json ---
let answer;
try {
  answer = JSON.parse(fs.readFileSync(path.join(dir, 'answer.json'), 'utf8'));
} catch (err) {
  console.log(`FAIL  answer.json unreadable/invalid: ${err.message}`);
  console.log('\nRESULT: FAIL');
  process.exit(1);
}
check('answer.json is a JSON object', answer !== null && typeof answer === 'object' && !Array.isArray(answer));
sameKeys(answer, ['regions', 'grand_units', 'grand_weighted'], 'answer.json top-level');

// --- 3. regions structure ---
const regions = answer.regions;
if (regions === null || typeof regions !== 'object' || Array.isArray(regions)) {
  fail('answer.json "regions" is not an object');
} else {
  sameKeys(regions, REGIONS, 'regions');

  for (const region of REGIONS) {
    const entry = regions[region];
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      fail(`regions.${region} is not an object`);
      continue;
    }
    sameKeys(entry, ['count', 'units', 'weighted'], `regions.${region}`);
    for (const field of ['count', 'units', 'weighted']) {
      check(`regions.${region}.${field} is a non-negative integer`, isInt(entry[field]), `got ${JSON.stringify(entry[field])}`);
    }
    const exp = recomputed[region];
    if (!exp) { fail(`no recomputation available for ${region}`); continue; }
    for (const field of ['count', 'units', 'weighted']) {
      check(`regions.${region}.${field} matches recomputation`, entry[field] === exp[field],
        `answer=${JSON.stringify(entry[field])} recomputed=${exp[field]}`);
    }
  }
}

// --- 4. grand totals: presence, type, internal consistency, recomputation ---
check('grand_units is a non-negative integer', isInt(answer.grand_units), `got ${JSON.stringify(answer.grand_units)}`);
check('grand_weighted is a non-negative integer', isInt(answer.grand_weighted), `got ${JSON.stringify(answer.grand_weighted)}`);

const sumUnits = REGIONS.reduce((s, r) => s + (recomputed[r] ? recomputed[r].units : 0), 0);
const sumWeighted = REGIONS.reduce((s, r) => s + (recomputed[r] ? recomputed[r].weighted : 0), 0);
const regionCount = regions && typeof regions === 'object' ? Object.keys(regions).length : 0;
check('regions contains exactly the four required regions', regionCount === REGIONS.length, `count=${regionCount}`);

check('grand_units matches recomputation', answer.grand_units === sumUnits,
  `answer=${JSON.stringify(answer.grand_units)} recomputed=${sumUnits}`);
check('grand_weighted matches recomputation', answer.grand_weighted === sumWeighted,
  `answer=${JSON.stringify(answer.grand_weighted)} recomputed=${sumWeighted}`);

if (regions && typeof regions === 'object') {
  const answeredUnits = REGIONS.reduce((s, r) => s + (regions[r] && isInt(regions[r].units) ? regions[r].units : 0), 0);
  const answeredWeighted = REGIONS.reduce((s, r) => s + (regions[r] && isInt(regions[r].weighted) ? regions[r].weighted : 0), 0);
  check('grand_units equals sum of answer regions', answer.grand_units === answeredUnits,
    `grand=${JSON.stringify(answer.grand_units)} sum=${answeredUnits}`);
  check('grand_weighted equals sum of answer regions', answer.grand_weighted === answeredWeighted,
    `grand=${JSON.stringify(answer.grand_weighted)} sum=${answeredWeighted}`);
}

// --- 5. source completeness: all four sources present and consumed ---
const present = fs.readdirSync(dir).filter((f) => /^(north|south|east|west)\.json$/.test(f));
check('all four region source files present', present.length === REGIONS.length, `found [${present.sort().join(',')}]`);
check('every source recomputed', REGIONS.every((r) => recomputed[r]), `regions=[${Object.keys(recomputed).join(',')}]`);

console.log(`\nRESULT: ${failures === 0 ? 'PASS' : 'FAIL (' + failures + ' check(s) failed)'}`);
process.exit(failures === 0 ? 0 : 1);
